    const sync = () => { el.style.left = b.art.x + "%"; el.style.top = b.art.y + "%"; el.style.setProperty("--sc", b.art.scale / 100); for (const k of ["x", "y", "scale"]) { const i = this.element.querySelector(`[data-p="art.${k}"]`); if (i) i.value = b.art[k]; } this.dirty = true; const sv = this.element.querySelector('[data-a="save"]'); if (sv) sv.disabled = false; };
